$content='<div class="page-head"><div><h1>Ustawienia systemowe</h1><p>Tryby awaryjne, lifecycle i retencja.</p></div></div>'.$message.'<form class="card" method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label><input type="checkbox" name="maintenance_mode" '.($settings->maintenanceMode()?'checked':'').'> Maintenance mode — blokuj nowe logowania użytkowników</label><label><input type="checkbox" name="external_login_emergency_disabled" '.($settings->externalLoginEmergencyDisabled()?'checked':'').'> Emergency disable — zablokuj logowania przez zewnętrznych IdP</label><label>Announcement banner<textarea name="announcement_banner" rows="3">'.Web::e($settings->announcement()??'').'</textarea></label><div class="form-row"><label>Blokada po braku aktywności — dni<input type="number" min="0" name="inactive_account_days" value="'.$settings->inactiveDays().'"></label><label>Retencja audytu — dni<input type="number" min="0" name="audit_retention_days" value="'.$settings->auditRetentionDays().'"></label></div><button class="primary">Zapisz</button></form><p><a class="button" href="/admin/housekeeping">Housekeeping</a> <a class="button" href="/admin/legal">Terms / Privacy</a> <a class="button" href="/admin/impersonation">Impersonation</a></p>';Web::page('System',$content,$admin);
